PARENT(m, n):
  if (m, n) = (2, 1)      return NONE            // the root
  if m > 3n               return (m - 2n, n)     // last move was B3
  if 2n < m <= 3n         return (n, m - 2n)     // last move was B2
  else                    return (n, 2n - m)     // last move was B1

ADDRESS(m, n):
  assert (m, n) is a Euclid seed
  W <- empty list
  (M, N) <- (m, n)
  while (M, N) != (2, 1):
      if   M > 3N:  append '3'
      elif M > 2N:  append '2'
      else:         append '1'
      (M, N) <- PARENT(M, N)          // first coordinate strictly decreases
  return reverse(W)

FOLLOW(word):                          // the inverse map
  (m, n) <- (2, 1)
  for ch in word:
      if ch = '1': (m, n) <- (2m - n, m)
      if ch = '2': (m, n) <- (2m + n, m)
      if ch = '3': (m, n) <- (m + 2n, n)
  return (m, n)

