"""Algorithm B -- Berggren descent: address word and depth by the slope trichotomy."""

from __future__ import annotations

from math import gcd
from typing import List, Optional, Tuple

Seed = Tuple[int, int]


def is_seed(m: int, n: int) -> bool:
    return 0 < n < m and gcd(m, n) == 1 and (m + n) % 2 == 1


def parent(s: Seed) -> Optional[Seed]:
    """Invert the Berggren move that produced s, or None if s is the root.

    On slopes the three moves are the Moebius maps

        B1: t -> 1/(2-t)   with image (1/2, 1),
        B2: t -> 1/(2+t)   with image (1/3, 1/2),
        B3: t -> t/(1+2t)  with image (0, 1/3),

    and these three windows are disjoint.  Comparing m with 2n and 3n therefore
    identifies the last move uniquely, and inverting it gives the parent.  The
    degenerate boundaries do not occur: m = 2n forces (m,n) = (2,1) by
    coprimality, and m = 3n forces (3,1), whose coordinate sum is even.
    """
    m, n = s
    if (m, n) == (2, 1):
        return None
    if m > 3 * n:            # last move was B3: (m,n) = (m0 + 2 n0, n0)
        return (m - 2 * n, n)
    if m > 2 * n:            # last move was B2: (m,n) = (2 m0 + n0, m0)
        return (n, m - 2 * n)
    return (n, 2 * n - m)    # last move was B1: (m,n) = (2 m0 - n0, m0)


def address(s: Seed) -> str:
    """The address word of a seed in {1,2,3}*, read from the root downwards.

    Correctness: the first coordinate strictly decreases at every step (the
    parent of (m,n) has first coordinate n or m - 2n, both < m), so the loop
    terminates, and by the trichotomy it terminates only at the root (2,1).
    Cost: O(1) arithmetic per step.  The number of steps is the depth, which
    is O(log m) along the middle spine but can be as large as m - 2: the left
    spine (k+2, k+1) has depth k while its hyperbolic radius is only
    Theta(log k).  Depth is therefore NOT controlled by hyperbolic distance.
    """
    if not is_seed(*s):
        raise ValueError("not a Euclid seed: %r" % (s,))
    letters: List[str] = []
    cur: Optional[Seed] = s
    while cur is not None and cur != (2, 1):
        m, n = cur
        letters.append("3" if m > 3 * n else ("2" if m > 2 * n else "1"))
        cur = parent(cur)
    return "".join(reversed(letters))


def follow(word: str) -> Seed:
    """The seed reached from the root by the given address word."""
    m, n = 2, 1
    for ch in word:
        if ch == "1":
            m, n = 2 * m - n, m
        elif ch == "2":
            m, n = 2 * m + n, m
        elif ch == "3":
            m, n = m + 2 * n, n
        else:
            raise ValueError("address letters must be 1, 2 or 3")
    return (m, n)


if __name__ == "__main__":
    for s in [(2, 1), (7, 4), (8, 1), (29, 12), (52, 51)]:
        w = address(s)
        assert follow(w) == s
        print("%-10s depth %-4d address %s" % (str(s), len(w), w if w else "(root)"))

