"""Algorithm E -- star-line arm decomposition and the totient count."""

from __future__ import annotations

from math import gcd
from typing import Dict, List, Tuple

Seed = Tuple[int, int]


def totient(k: int) -> int:
    """Euler's phi by trial division; O(sqrt k)."""
    result, x, p = k, k, 2
    while p * p <= x:
        if x % p == 0:
            while x % p == 0:
                x //= p
            result -= result // p
        p += 1
    if x > 1:
        result -= result // x
    return result


def one_star_arms(u: int, length: int) -> Dict[int, List[Seed]]:
    """Decompose the 1-star line of odd charge u into its maximal B1-arms.

    In charge coordinates (u, n) the node set of the whole tree is the grid
    {u odd, gcd(u,n) = 1}; the line of charge u is the row of that grid, and
    B1 acts on it by n -> n + u.  The maximal arms are therefore indexed by
    the residues r in [1, u] coprime to u, and the k-th node of arm r is
    (r + ku + u, r + ku).  The count of arms is phi(u) = phi(2u), since u is
    odd.  Cost O(u log u + u * length).
    """
    if u <= 0 or u % 2 == 0:
        raise ValueError("the 1-star realises only odd charges")
    arms: Dict[int, List[Seed]] = {}
    for r in range(1, u + 1):
        if gcd(u, r) != 1:
            continue
        arms[r] = [(r + k * u + u, r + k * u) for k in range(length)]
    return arms


def zero_star_arms(n: int, length: int) -> Dict[int, List[Seed]]:
    """Decompose the 0-star line of charge n into its maximal B3-arms.

    The line of charge n consists of the seeds (m, n) with gcd(m,n) = 1 and
    m + n odd, and B3 acts by m -> m + 2n, of period 2n.  The shift m -> m + n
    turns the two conditions into the single condition gcd(2n, m + n) = 1, so a
    window of length 2n contains exactly phi(2n) admissible residues: the line
    carries phi(2n) maximal arms.  Cost O(n log n + n * length).
    """
    if n <= 0:
        raise ValueError("charge must be positive")
    arms: Dict[int, List[Seed]] = {}
    for m in range(n + 1, 3 * n + 1):
        if gcd(m, n) == 1 and (m + n) % 2 == 1:
            arms[m] = [(m + 2 * k * n, n) for k in range(length)]
    return arms


